def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all digits are 9, the next palindrome is 10..01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)
        # Construct palindrome by mirroring left half to right half
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            p = left + left[::-1]
        else:
            p = left + left[-2::-1]

        if int(p) >= int(s):
            s = p
        else:
            # increment the left half and then mirror again
            left_int = int(left) + 1
            left = str(left_int)
            if len(left) > half:
                # length increased, e.g. 999 -> 1000
                length += 1
                s = '1' + ('0' * (length - 1))
            else:
                if length % 2 == 0:
                    s = left + left[::-1]
                else:
                    s = left + left[-2::-1]

