def anti_shuffle(s):
    import re
    parts = re.findall(r'\s+|\S+', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            sorted_part = ''.join(sorted(part))
            result.append(sorted_part)
    return ''.join(result)

